#include <bits/stdc++.h>
using namespace std;

long long int value(vector<long long int> &p, long long int n, long long int a, long long int b) {
    long long int one = p[a];
    long long int two = p[a + 2 * b];
    long long int three = p[3 * n - 2 * a - b];
    return 2 * one + two + 3 * three;
}

int main() {
    long long int t;
    cin >> t;
    
    while (t--) {
        long long int n;
        cin >> n;
        
        long long int m = 3 * n;
        vector<long long int> v(m);
        
        long long int i = 0;
        while (i < m) {
            cin >> v[i];
            i = i + 1;
        }
        
        sort(v.begin(), v.end());
        reverse(v.begin(), v.end());
        
        vector<long long int> p(m + 1, 0);
        i = 0;
        while (i < m) {
            p[i + 1] = p[i] + v[i];
            i = i + 1;
        }
        
        long long int ans = 0;
        
        long long int a = 0;
        while (a <= n) {
            long long int lo = 0;
            long long int hi = n - a;
            while (lo < hi) {
                long long int mid = (lo + hi) / 2;
                if (value(p, n, a, mid + 1) >= value(p, n, a, mid)) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            
            long long int cur = value(p, n, a, lo);
            if (cur > ans) {
                ans = cur;
            }
            
            a = a + 1;
        }
        
        cout << ans << endl;
    }
    
    return 0;
}
